const CIT_TERMS_RE = CIT_TERMS.map(([s, b]) => [new RegExp("^(?:" + s + ")$"), b, s]);
const CIT_CAPITALS = {"canada":"Ottawa", "alberta":"Edmonton", "british columbia":"Victoria", "bc":"Victoria", "manitoba":"Winnipeg", "new brunswick":"Fredericton", "newfoundland and labrador":"St. John's", "newfoundland":"St. John's", "nova scotia":"Halifax", "ontario":"Toronto", "prince edward island":"Charlottetown", "pei":"Charlottetown", "quebec":"Quebec City", "saskatchewan":"Regina", "yukon":"Whitehorse", "the yukon":"Whitehorse", "northwest territories":"Yellowknife", "the northwest territories":"Yellowknife", "nwt":"Yellowknife", "nunavut":"Iqaluit"};
function citizen(q){
  const out = body => ({kind:"text", title:null, body, src:"Nimble citizenship", source:"Nimble citizenship"});
  const cap = /^(?:what is )?(?:the )?capital (?:city )?of (?:the province of |the territory of )?([a-z. ]+?)(?: province| territory)?$/.exec(q);
  if(cap && CIT_CAPITALS[cap[1]]) return out(CIT_CAPITALS[cap[1]] + ".");
  for(const [s, body] of CIT_FACTS) if(new RegExp(s).test(q)) return out(body);
  const tb = termAsk(q.replace(/^(?:who|what) (?:was|were|is|are) /, "").replace(/ in canada$/, ""), CIT_TERMS_RE, []); return tb ? out(tb) : null;
}
